// Merge default dan pengaturan pengguna
var settings = Object.assign({}, userSettings);

// Objek AdminSettings untuk mengelola pengaturan
var AdminSettings = {
  // Inisialisasi pengaturan
  AdminSettingsInit: function () {
    AdminSettings.ManageSidebarType();
  },

  // Mengatur tipe sidebar (full atau mini-sidebar)
  ManageSidebarType: function () {
    switch (settings.SidebarType) {
      case "full":
        document.body.setAttribute("data-sidebartype", "full");
        var setsidebartype = function () {
          var width = window.innerWidth > 0 ? window.innerWidth : this.screen.width;
          if (width < 1300) {
            document.body.setAttribute("data-sidebartype", "mini-sidebar");
          } else {
            document.body.setAttribute("data-sidebartype", "full");
          }
        };
        window.addEventListener("DOMContentLoaded", setsidebartype);
        window.addEventListener("resize", setsidebartype);
        break;

      case "mini-sidebar":
        document.body.setAttribute("data-sidebartype", "mini-sidebar");
        break;

      default:
        document.body.setAttribute("data-sidebartype", "full"); // Default ke full jika tidak ada pengaturan
    }
  },

  // Mengatur tema (light/dark)
  ManageDarkThemeLayout: function () {
    switch (settings.Theme) {
      case "light":
        setTheme("light", ["light-logo"], ["moon"], ["sun"]);
        break;
      case "dark":
        setTheme("dark", ["dark-logo"], ["sun"], ["moon"]);
        break;
      default:
        setTheme("light", ["light-logo"], ["moon"], ["sun"]); // Default ke light
    }

    function setTheme(theme, hideElements, showElements, hideElements2) {
      document.documentElement.setAttribute("data-bs-theme", theme);
      hideElements.forEach((el) =>
        document.querySelectorAll(`.${el}`).forEach((e) => (e.style.display = "none"))
      );
      showElements.forEach((el) =>
        document.querySelectorAll(`.${el}`).forEach((e) => (e.style.display = "flex"))
      );
      hideElements2.forEach((el) =>
        document.querySelectorAll(`.${el}`).forEach((e) => (e.style.display = "none"))
      );
    }
  },

  // Mengatur tema warna
  ManageColorThemeLayout: function () {
    const { ColorTheme } = settings;
    if (ColorTheme) {
      document.documentElement.setAttribute("data-color-theme", ColorTheme);
    }
  },
};

// Event listener saat DOM selesai dimuat
document.addEventListener("DOMContentLoaded", function () {
  // Inisialisasi pengaturan
  AdminSettings.AdminSettingsInit();

  // Mengatur tema dark/light melalui klik ikon
  function handleTheme() {
    function setThemeAttributes(theme, darkDisplay, lightDisplay, sunDisplay, moonDisplay) {
      document.documentElement.setAttribute("data-bs-theme", theme);
      document.querySelectorAll(`.${darkDisplay}`).forEach((el) => (el.style.display = "none"));
      document.querySelectorAll(`.${lightDisplay}`).forEach((el) => (el.style.display = "flex"));
      document.querySelectorAll(`.${sunDisplay}`).forEach((el) => (el.style.display = "none"));
      document.querySelectorAll(`.${moonDisplay}`).forEach((el) => (el.style.display = "flex"));

      // Simpan ke database via AJAX (opsional)
      fetch('/theme/update', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
        },
        body: JSON.stringify({ theme: theme }),
      })
        .then((response) => response.json())
        .then((data) => {
          if (!data.success) console.error('Failed to save theme:', data.message);
        })
        .catch((error) => console.error('Error:', error));
    }

    document.querySelectorAll(".moon").forEach((element) => {
      element.addEventListener("click", () =>
        setThemeAttributes("dark", "dark-logo", "light-logo", "moon", "sun")
      );
    });

    document.querySelectorAll(".sun").forEach((element) => {
      element.addEventListener("click", () =>
        setThemeAttributes("light", "light-logo", "dark-logo", "sun", "moon")
      );
    });
  }
  handleTheme();

  // Toggle sidebar
  function handleSidebar() {
    document.querySelectorAll(".sidebartoggler").forEach(function (element) {
      element.addEventListener("click", function () {
        document.getElementById("main-wrapper").classList.toggle("show-sidebar");
        document.querySelectorAll(".sidebarmenu").forEach(function (el) {
          el.classList.toggle("close");
        });
        var dataTheme = document.body.getAttribute("data-sidebartype");
        if (dataTheme === "full") {
          document.body.setAttribute("data-sidebartype", "mini-sidebar");
        } else {
          document.body.setAttribute("data-sidebartype", "full");
        }
      });
    });
  }
  handleSidebar();
});